(()=>{const t=window.customNotes;t.tryExport.exportJson=async function(){return JSON.stringify(await Promise.all((await window.customNotes.storage.getAllNotes()).map((t=>t.json()))))},t.tryExport.importJson=async function(a){JSON.parse(a).forEach((async a=>{const o=await Promise.all((await t.storage.getNotesByPath(a.pagePathname)).map((t=>t.json())));t.manageNoteSaving(a,o)}))}})();